import{_ as e,o as a,c as r,ai as n}from"./chunks/framework.ampVZV4B.js";const A=JSON.parse('{"title":"Agent 面试 · 概念与边界","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/concepts-interview.md","filePath":"guide/agent/concepts-interview.md"}'),d={name:"guide/agent/concepts-interview.md"};function l(i,t,o,h,g,s){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="agent-面试-·-概念与边界" tabindex="-1">Agent 面试 · 概念与边界 <a class="header-anchor" href="#agent-面试-·-概念与边界" aria-label="Permalink to “Agent 面试 · 概念与边界”">​</a></h1><blockquote><p>先分清名词，避免面试一上来把 Chat、RAG、Agent 混着说。</p></blockquote><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>Agent 到底是什么？和 Chatbot 差在哪？</li><li>RAG、Agent、微调分别解决什么？</li><li>什么时候不该上 Agent？</li><li>Code Agent 和 Worker Agent 有什么区别？</li><li>「多 Agent」和「一个 Agent 多个工具」怎么理解？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-agent-一句话" tabindex="-1">1）Agent 一句话 <a class="header-anchor" href="#_1-agent-一句话" aria-label="Permalink to “1）Agent 一句话”">​</a></h3><blockquote><p>Agent = <strong>目标 + 模型决策 + 工具执行 + 循环</strong>，直到完成、失败或触达上限。</p></blockquote><p>不是「模型更聪明」，而是<strong>能碰外部世界</strong>（API、库、浏览器、代码仓），并且有工程边界。</p><table tabindex="0"><thead><tr><th></th><th>Chat / 单次补全</th><th>Agent</th></tr></thead><tbody><tr><td>输入输出</td><td>文本进、文本出</td><td>可多轮，中间有工具结果</td></tr><tr><td>行动</td><td>基本不碰系统</td><td>调工具改状态</td></tr><tr><td>失败形态</td><td>答错、胡说</td><td>死循环、乱调工具、成本炸</td></tr></tbody></table><h3 id="_2-rag-agent-微调" tabindex="-1">2）RAG / Agent / 微调 <a class="header-anchor" href="#_2-rag-agent-微调" aria-label="Permalink to “2）RAG / Agent / 微调”">​</a></h3><table tabindex="0"><thead><tr><th></th><th>RAG</th><th>Agent</th><th>微调</th></tr></thead><tbody><tr><td>问题类型</td><td>「文档/制度里怎么说」</td><td>「帮我把事做完」</td><td>「口吻/格式/领域要长期贴」</td></tr><tr><td>核心动作</td><td>检索 → 塞上下文</td><td>规划 → 调工具 → 观察</td><td>改权重</td></tr><tr><td>知识更新</td><td>改库</td><td>靠工具与系统</td><td>再训练</td></tr><tr><td>默认</td><td>知识在外部时优先</td><td>真要多步办事</td><td>最后才考虑</td></tr></tbody></table><p><strong>默认顺序（可背）：</strong> Prompt / 结构化输出 → RAG → Agent → 微调。</p><h3 id="_3-什么时候别上-agent" tabindex="-1">3）什么时候别上 Agent <a class="header-anchor" href="#_3-什么时候别上-agent" aria-label="Permalink to “3）什么时候别上 Agent”">​</a></h3><ul><li>单次问答、写摘要、简单分类就够</li><li>没有可靠工具 / 权限说不清</li><li>业务规则用 if-else 或工作流引擎更稳、更便宜</li><li>团队还不会做超时、重试、审计——先别上「自主」</li></ul><p>一句话：<strong>能流程化的先流程化；Agent 补「决策不确定、要调多种工具」的缝。</strong></p><h3 id="_4-code-vs-worker" tabindex="-1">4）Code vs Worker <a class="header-anchor" href="#_4-code-vs-worker" aria-label="Permalink to “4）Code vs Worker”">​</a></h3><ul><li><strong>Code Agent</strong>：读仓、改文件、跑命令、出 PR（Cursor、Claude Code、Codex、通义灵码…）</li><li><strong>Worker Agent</strong>：办事——文档、表格、浏览器、本地文件（Operator、WorkBuddy…）</li></ul><p>面试举例时先说清你做的是哪一类，再讲链路。</p><h3 id="_5-多-agent" tabindex="-1">5）多 Agent <a class="header-anchor" href="#_5-多-agent" aria-label="Permalink to “5）多 Agent”">​</a></h3><p>常见两种说法：</p><ul><li><strong>一个主 Agent + 多个工具</strong>（多数业务够用）</li><li><strong>多个角色 Agent</strong>（规划 / 执行 / 审查）串或并行，要有汇总与权限</li></ul><p>别吹「我们上了多智能体」——讲清<strong>为什么拆、怎么汇合、失败谁负责</strong>。</p><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「那 LangChain / 自研编排差在哪？」→ 框架是加速器；核心仍是工具契约、状态、观测。</li><li>「和传统工作流引擎比？」→ 引擎路径确定；Agent 路径由模型动态选工具，不确定性更高，更要护栏。</li></ul>',27)])])}const b=e(d,[["render",l]]);export{A as __pageData,b as default};
